questionvariables.text:
/* Design: base a0(x-m0)^2(x-n0); distractors: reflect (-base), swap (touch and cross exchanged), mirror (base(-x)). Each curve is stored as [c, r2, r1] for c(x-r2)^2(x-r1). The graph order is a balanced curated permutation per index: each of the four curves appears at each letter 2 or 3 times, and the correct letter by index is A B C A C D A B D C. Keep it balanced so no letter is always the correct or the reflected graph. Source: original. */
L: [[1,-1,2],[-1,1,-2],[1,2,-1],[-1,3,-1],[1,-2,3],[-1,-2,1],[1,-3,1],[-1,1,4],[1,1,-2],[-1,-2,3]];
ix: 1+rand(10);
a0: L[ix][1]; m0: L[ix][2]; n0: L[ix][3];
gord: [[1,3,4,2],[4,1,3,2],[2,4,1,3],[1,2,4,3],[2,3,1,4],[3,4,2,1],[1,3,2,4],[3,1,4,2],[4,2,3,1],[3,2,1,4]][ix];
ffac: a0*(x-m0)^2*(x-n0);
Bs: [a0,m0,n0]; Rf: [-a0,m0,n0]; Sw: [a0,n0,m0]; Mi: [-a0,-m0,-n0];
Ty: [Bs,Rf,Sw,Mi];
G: makelist(Ty[gord[j]],j,1,4);
gpos: [[1,4,2,3],[2,4,3,1],[3,1,4,2],[1,2,4,3],[3,1,2,4],[4,3,1,2],[1,3,2,4],[2,4,1,3],[4,2,3,1],[3,2,1,4]][ix];
pos: gpos[1]; pr: gpos[2]; ps: gpos[3]; pm: gpos[4];
lets: ["A","B","C","D"];
lc: lets[pos]; lr: lets[pr]; ls: lets[ps]; lm: lets[pm];
opts: [["A",is(pos=1),"Graph A"],["B",is(pos=2),"Graph B"],["C",is(pos=3),"Graph C"],["D",is(pos=4),"Graph D"]];
kk: abs(n0-m0)/3;
Yb: max(ceiling(1.4*4*kk^3),3);
W: max(abs(m0),abs(n0))+2;
